def create_plans(apps, schema_editor):
    Plan = apps.get_model('billing', 'Plan')
    for plan_data in PLANS:
        Plan.objects.get_or_create(
            plan_type=plan_data['plan_type'],
            interval=plan_data['interval'],
            defaults=plan_data,
        )


def create_subscriptions_for_existing_orgs(apps, schema_editor):
    """Create free subscriptions for existing organizations."""
    Organization = apps.get_model('accounts', 'Organization')
    Plan = apps.get_model('billing', 'Plan')
    Subscription = apps.get_model('billing', 'Subscription')

    from django.utils import timezone
    from datetime import timedelta

    free_plan = Plan.objects.filter(plan_type='free', interval='month').first()
    if not free_plan:
        return

    for org in Organization.objects.filter(deleted_at__isnull=True):
        Subscription.objects.get_or_create(
            organization=org,
            defaults={
                'plan': free_plan,
                'status': 'active',
                'interval': 'month',
                'current_period_start': timezone.now(),
                'current_period_end': timezone.now() + timedelta(days=30),
                'usage_reset_date': timezone.now().date(),
            },
        )


